/* ─── formatting ─── */
const fmtSize=b=>{if(b==null)return'';if(b<1024)return b+' B';const u=['KB','MB','GB','TB'];let i=-1;do{b/=1024;i++}while(b>=1024&&i<u.length-1);return b.toFixed(b<10?2:b<100?1:0)+' '+u[i]};
const pad=(n,l=2)=>String(Math.floor(n)).padStart(l,'0');
const fmtDur=s=>{if(s==null||isNaN(s))return'';s=Math.round(s);const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;return(h?pad(h)+':':'')+pad(m)+':'+pad(x)};
const fmtDate=(t,withTime)=>{if(!t)return'';const d=new Date(t);const o={month:'2-digit',day:'2-digit',year:'numeric'};if(withTime)Object.assign(o,{hour:'numeric',minute:'2-digit'});return d.toLocaleString('en-US',o)};
const ago=t=>{const s=(Date.now()-t)/1000;if(s<60)return'just now';if(s<3600)return Math.floor(s/60)+'m ago';if(s<86400)return Math.floor(s/3600)+'h ago';if(s<86400*30)return Math.floor(s/86400)+'d ago';return fmtDate(t)};
const ini=n=>(n||'?').split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase();
const fmtTC=(sec,fps,mode)=>{fps=fps||30;const f=Math.round(sec*fps);if(mode==='frames')return String(f);const fr=f%Math.round(fps);const s=Math.floor(f/Math.round(fps));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;if(mode==='standard')return(h?pad(h)+':':'')+pad(m)+':'+pad(x)+'.'+pad(Math.round(fr/fps*100));return pad(h)+':'+pad(m)+':'+pad(x)+(Number.isInteger(fps)?':':';')+pad(fr)};
const parseTC=(str,fps)=>{fps=fps||30;str=str.trim();if(/^\d+$/.test(str))return +str/fps;const m=str.match(/^(?:(\d+):)?(\d+):(\d+)(?:[:;.](\d+))?$/);if(!m)return null;const h=+(m[1]||0),mm=+m[2],s=+m[3];let f=+(m[4]||0);if(str.includes('.')&&m[4])f=f/100*fps;return h*3600+mm*60+s+f/fps};
/* ─── status / fields ─── */
const STATUS=[{k:'needs_review',n:'Needs Review',c:'needs_review'},{k:'in_progress',n:'In Progress',c:'in_progress'},{k:'approved',n:'Approved',c:'approved'}];
const statusName=k=>(STATUS.find(s=>s.k===k)||{}).n||'';
const statusPill=k=>k?`<span class="status ${k}">${esc(statusName(k))}</span>`:`<span class="status none">Set status</span>`;
const typeOf=(mime,name)=>{mime=mime||'';const ext=(name||'').split('.').pop().toLowerCase();if(mime.startsWith('video/')||['mp4','mov','m4v','webm','mkv','mxf','avi','prores'].includes(ext))return'Video';if(mime.startsWith('image/')||['jpg','jpeg','png','gif','webp','heic','tif','tiff','psd','svg','exr','dng'].includes(ext))return'Image';if(mime.startsWith('audio/')||['mp3','wav','aac','m4a','flac','aif','aiff','ogg'].includes(ext))return'Audio';if(['glb','gltf','obj','fbx','usdz','stl'].includes(ext))return'3D';if(mime==='application/pdf'||['pdf','doc','docx','txt','md','pptx','key','xlsx','csv'].includes(ext))return'Document';return'Other'};
const cur=a=>a.versions[a.cur]||a.versions[a.versions.length-1];
const metaOf=a=>(cur(a)||{}).meta||{};
