function appearanceMenu(anchor,pf,done){const seg=(k,opts)=>`<span class="seg">${opts.map(([v,l])=>`<button data-k="${k}" data-v="${v}" class="${pf[k]===v?'on':''}">${l}</button>`).join('')}</span>`;const html=`<h5>Appearance</h5><div class="row"><span class="lab">Layout</span>${seg('layout',[['grid',ico('grid')],['list',ico('list')]])}</div><div class="row"><span class="lab">Card Size</span>${seg('size',[['s','S'],['m','M'],['l','L']])}</div><div class="row"><span class="lab">Aspect Ratio</span>${seg('ar',[['16:9','16:9'],['4:3','4:3'],['9:16','9:16']])}</div><div class="row"><span class="lab">Thumbnail Scale</span>${seg('scale',[['fit','Fit'],['fill','Fill']])}</div><div class="row"><span class="lab">Show Card Info</span><span class="tog ${pf.info?'on':''}" data-t="info"></span></div><div class="row"><span class="lab">Titles</span>${seg('titles',[[1,'1 Line'],[2,'2 Lines']])}</div><div class="row"><span class="lab">Flatten Folders</span><span class="tog ${pf.flatten?'on':''}" data-t="flatten"></span></div>`;const p=pop(anchor,html,{w:300});$$('[data-k]',p).forEach(b=>b.onclick=()=>{let v=b.dataset.v;if(b.dataset.k==='titles')v=+v;pf[b.dataset.k]=v;done()});$$('[data-t]',p).forEach(t=>t.onclick=()=>{pf[t.dataset.t]=!pf[t.dataset.t];done()})}
function fieldsMenu(anchor,visible,done,opt={}){const fs=allFields();const draw=(q)=>{const list=fs.filter(f=>!q||f.n.toLowerCase().includes(q));return`<div class="row" style="padding:6px 6px 2px"><input type="search" id="fsQ" placeholder="Search fields" value="${esc(q||'')}"></div><h5>Fields (${fs.length})</h5><div id="fsList">${list.map(f=>`<div class="row" data-f="${f.k}" draggable="true"><span class="grip">⋮⋮</span><span class="lab">${ico(fieldIcon(f))}${esc(f.n)}${f.custom?`<button class="ib" style="width:20px;height:20px;margin-left:4px" data-del="${f.custom.id}" title="Delete field">${ico('x')}</button>`:''}</span><span class="tog ${visible.includes(f.k)?'on':''}" data-t="${f.k}"></span></div>`).join('')}</div><hr>${opt.noManage?'':`<div class="mi" id="fsManage">${ico('gear')}Manage Fields<span class="sub">${ico('ext')}</span></div><div class="mi" id="fsNew">${ico('plus')}New Field</div>`}`};const p=pop(anchor,draw(''),{w:320});const bind=()=>{$$('[data-t]',p).forEach(t=>t.onclick=()=>{const k=t.dataset.t;const i=visible.indexOf(k);if(i>=0)visible.splice(i,1);else visible.push(k);t.classList.toggle('on',i<0);done(visible.slice(),true)});$$('[data-del]',p).forEach(b=>b.onclick=()=>{const id=b.dataset.del;confirmBox('Delete field?','Values stored on assets for this field will be removed.','Delete',()=>{S.customFields=S.customFields.filter(c=>c.id!==id);S.items.forEach(a=>{if(a.custom)delete a.custom[id]});const i=visible.indexOf('c_'+id);if(i>=0)visible.splice(i,1);save();done(visible.slice())})});const q=$('#fsQ',p);q.oninput=()=>{p.innerHTML=draw(q.value.trim().toLowerCase());bind();$('#fsQ',p).focus()};const m=$('#fsManage',p);if(m)m.onclick=()=>{closePop();manageFields()};const n=$('#fsNew',p);if(n)n.onclick=()=>{closePop();newField(()=>done(visible.slice()))};let dragK=null;$$('[data-f]',p).forEach(r=>{r.ondragstart=e=>{dragK=r.dataset.f;e.dataTransfer.effectAllowed='move'};r.ondragover=e=>e.preventDefault();r.ondrop=e=>{e.preventDefault();if(!dragK||dragK===r.dataset.f)return;const a=visible.indexOf(dragK),b=visible.indexOf(r.dataset.f);if(a>=0&&b>=0){visible.splice(a,1);visible.splice(b,0,dragK);done(visible.slice(),true)}}})};bind()}
function newField(done){modal(`<h3>New Field<button class="x">✕</button></h3><label>Name</label><input type="text" id="nfName" placeholder="e.g. Client approval"><label>Type</label><select id="nfType"><option value="text">Text</option><option value="long">Long text</option><option value="num">Number</option><option value="date">Date</option><option value="bool">Checkbox</option><option value="rating">Rating (1–5)</option><option value="select">Select</option><option value="person">Person</option><option value="tags">Tags</option></select><label>Options (for Select; comma separated)</label><input type="text" id="nfOpts"><div class="btns"><button class="btn ghost" id="nfNo">Cancel</button><button class="btn gold" id="nfYes">Create</button></div>`);$('#nfNo').onclick=closeModal;$('#nfYes').onclick=()=>{const n=$('#nfName').value.trim();if(!n)return;S.customFields.push({id:uid(),name:n,type:$('#nfType').value,opts:$('#nfOpts').value.split(',').map(s=>s.trim()).filter(Boolean)});save();closeModal();toast('Field created');done&&done()}}
