function sortMenu(anchor,pf,done){const base=[['custom','Custom'],['name','Name'],['uploaded','Date Uploaded'],['status','Status'],['duration','Duration'],['fsize','File Size']];const rest=allFields().filter(f=>!['status','duration','fsize','uploaded'].includes(f.k));const items=[{h:'Sort by'},...base.map(([k,n])=>({n,tick:true,on:pf.sort===k,fn:()=>{pf.sort=k;done()}})),'-',{html:`<div class="row"><span class="lab">Direction</span><span class="seg"><button data-d="1" class="${pf.sortDir===1?'on':''}">Asc</button><button data-d="-1" class="${pf.sortDir===-1?'on':''}">Desc</button></span></div>`},'-',{h:'Fields'},...rest.map(f=>({n:f.n,tick:true,on:pf.sort===f.k,fn:()=>{pf.sort=f.k;done()}}))];const p=menu(anchor,items,{w:260});$$('[data-d]',p).forEach(b=>b.onclick=()=>{pf.sortDir=+b.dataset.d;done()})}
