function selbar(c,pr){let bar=$('.selbar',c);if(!SEL.size){if(bar)bar.remove();return}const items=[...SEL].map(item).filter(Boolean);const nF=items.filter(i=>i.kind==='folder').length,nA=items.length-nF;const label=nF&&!nA?`${nF} Folder${nF>1?'s':''} selected`:!nF?`${nA} Asset${nA>1?'s':''} selected`:`${items.length} Items selected`;if(!bar){bar=document.createElement('div');bar.className='selbar';c.appendChild(bar)}bar.innerHTML=`<b>${label}</b><button class="x" id="selX">✕</button><button class="ib" id="selMore">${ico('more')}</button><button class="btn soft sm" id="selCopy">${ico('link')}Copy ${nF&&!nA?'Folder':'Asset'} URL</button><button class="btn soft sm" id="selDl">${ico('dl')}Download</button><button class="btn soft sm" id="selAcc">${ico('lock')}Manage Access</button>`;$('#selX',bar).onclick=()=>{SEL.clear();c._updateSel()};$('#selMore',bar).onclick=e=>menu(e.currentTarget,[{n:'Delete',ic:'trash',fn:()=>deleteItems([...SEL])},{n:'Move to',ic:'move',fn:()=>pickFolder('Move to',ids=>moveItems([...SEL],ids.pid,ids.fid))},{n:'Duplicate',ic:'dup',fn:()=>duplicateItems([...SEL])},{n:'Copy to',ic:'copy',fn:()=>pickFolder('Copy to',ids=>duplicateItems([...SEL],ids))},'-',{n:'Set status',ic:'check',sub:ico('chev'),keep:true,fn:(e,el)=>menu(el,STATUS.map(st=>({n:st.n,fn:()=>{[...SEL].map(item).filter(i=>i&&i.kind==='asset').forEach(a=>{a.status=st.k;syncPipeline(a)});save();render()}})).concat([{n:'No status',fn:()=>{[...SEL].map(item).forEach(a=>{if(a)a.status=null});save();render()}}]))}, {n:'Add to collection',ic:'coll',fn:()=>addToCollection([...SEL])},{n:'Create Share Link',ic:'share',fn:()=>createShare(pr.id,[...SEL])}],{above:true});$('#selCopy',bar).onclick=()=>copyText([...SEL].map(id=>APP_PATH+(item(id).kind==='folder'?`#/p/${pr.id}/f/${id}`:'#/view/'+id)).join('\n'),'URL copied');$('#selDl',bar).onclick=()=>downloadItems([...SEL]);$('#selAcc',bar).onclick=()=>manageAccess(items[0])}
