 if(t==='person'){const p=pop(anchor,`<div class="row"><input type="search" id="peQ" placeholder="Search people"></div>${people().map(n=>`<div class="mi ${v===n?'on':''}" data-p="${esc(n)}">${avatar(n)}<span>${esc(n)}</span><span class="tick">${ico('check')}</span></div>`).join('')}<hr><div class="mi" data-p="">${ico('x')}Unassign</div>`,{w:220});$$('[data-p]',p).forEach(el=>el.onclick=()=>{closePop();fin(el.dataset.p||null)});$('#peQ',p).oninput=e=>{const q=e.target.value.toLowerCase();$$('[data-p]',p).forEach(el=>el.style.display=el.textContent.toLowerCase().includes(q)?'':'none')};return}
 if(t==='rating'){const p=pop(anchor,`<div class="row" style="justify-content:center;gap:4px">${[1,2,3,4,5].map(n=>`<b data-r="${n}" style="font-size:22px;cursor:pointer;color:${n<=(v||0)?'var(--acc)':'#3a3a40'}">★</b>`).join('')}</div><div class="mi" data-r="0">${ico('x')}Clear rating</div>`,{w:200});$$('[data-r]',p).forEach(el=>el.onclick=()=>{closePop();fin(+el.dataset.r||null)});return}
