let UP_TARGET=null;
function uploadTarget(){if(UP_TARGET)return UP_TARGET;const r=route().parts;if(r[0]==='p')return {pid:r[1],fid:r[2]==='f'?r[3]:null,opt:{}};return {pid:S.projects[0].id,fid:null,opt:{}}}
function bindUploadInputs(){const fi=$('#fileIn'),fo=$('#folderIn');fi.onchange=async()=>{const t=uploadTarget();UP_TARGET=null;const files=[...fi.files];fi.value='';fi.multiple=true;if(!files.length)return;if(t.version){await addVersion(t.version,files[0]);save();render();return}ingestFiles(files,t.pid,t.fid,t.opt)};fo.onchange=()=>{const t=uploadTarget();UP_TARGET=null;const files=[...fo.files];fo.value='';ingestFiles(files,t.pid,t.fid,{keepPaths:true})}}
function pickUpload(pid,fid,opt={}){UP_TARGET={pid,fid,opt};const inp=$('#fileIn');inp.multiple=true;inp.click()}
function pickUploadFolder(pid,fid){UP_TARGET={pid,fid,opt:{}};$('#folderIn').click()}
function pickVersion(a){UP_TARGET={version:a};const inp=$('#fileIn');inp.multiple=false;inp.click()}
async function ingestEntries(dt,pid,fid){const items=[...(dt.items||[])];const files=[];const walk=async(entry,path)=>{if(entry.isFile){await new Promise(r=>entry.file(f=>{try{Object.defineProperty(f,'relPath',{value:path+f.name})}catch(e){}files.push(f);r()},()=>r()))}else if(entry.isDirectory){const rd=entry.createReader();let batch;do{batch=await new Promise(r=>rd.readEntries(r,()=>r([])));for(const e of batch)await walk(e,path+entry.name+'/')}while(batch.length)}};let used=false;for(const it of items){const e=it.webkitGetAsEntry&&it.webkitGetAsEntry();if(e){used=true;await walk(e,'')}}if(!used)[...dt.files].forEach(f=>files.push(f));ingestFiles(files,pid,fid,{keepPaths:true})}
async function ingestFiles(files,pid,fid,opt={}){files=files.filter(f=>!f.name.startsWith('.'));if(!files.length)return;const folderCache={};const ensureFolder=(path)=>{if(!path)return fid||null;if(folderCache[path])return folderCache[path];const parts=path.split('/');const parentPath=parts.slice(0,-1).join('/');const parent=ensureFolder(parentPath);const name=parts[parts.length-1];let f=children(pid,parent).find(i=>i.kind==='folder'&&i.name===name);if(!f){f={id:uid(),kind:'folder',pid,parent,name,created:Date.now(),uploader:ME.name,order:children(pid,parent).length,versions:[],comments:[],seen:[]};S.items.push(f)}folderCache[path]=f.id;return f.id};
 const jobs=files.map(f=>({id:uid(),name:f.name,size:f.size,pct:0,state:'queued',file:f}));U.push(...jobs);renderBadges();openSide('uploads');let made=0;
 for(const j of jobs){j.state='uploading';renderUploads();try{const rel=opt.keepPaths?(j.file.relPath||j.file.webkitRelativePath||''):'';const dir=rel.includes('/')?rel.split('/').slice(0,-1).join('/'):'';const parent=ensureFolder(dir);const a=await createAsset(j.file,pid,parent,p=>{j.pct=p;renderUploads()},opt);if(opt.card){a.card=opt.card;pipeUpdate(opt.card,{frameio:reviewLink(a)});opt.card=null}j.state='done';j.pct=100;j.aid=a.id;made++}catch(e){console.error(e);j.state='error';j.err=e.message||'failed'}renderUploads();save();render()}
 renderBadges();if(!U.some(j=>j.state==='uploading'||j.state==='queued'))setTimeout(()=>{const sp=$('#sidePanel');if(sp.dataset.kind==='uploads'&&!U.some(j=>j.state==='uploading'))closeSide()},1500);if(made){touch(pid);notify(`${ME.name} uploaded ${made} asset${made>1?'s':''}`,`#/p/${pid}${fid?'/f/'+fid:''}`);toast(`${made} upload${made>1?'s':''} complete`)}}
async function createAsset(file,pid,parent,onp){const a={id:uid(),kind:'asset',pid,parent:parent||null,name:file.name.replace(/\.[^.]+$/,''),created:Date.now(),uploader:ME.name,order:children(pid,parent).length,status:null,assignee:null,keywords:[],notes:'',rating:null,custom:{},versions:[],cur:0,comments:[],seen:[],transcript:null,captions:[],card:null};onp(5);await addVersion(a,file,onp);S.items.push(a);return a}
async function addVersion(a,file,onp=()=>{}){const v={id:uid(),srcName:file.name,created:Date.now(),uploader:ME.name,media:null,meta:{size:file.size,mime:file.type,type:typeOf(file.type,file.name),format:(file.name.split('.').pop()||'').toUpperCase()}};onp(15);try{Object.assign(v.meta,await probeMedia(file,v.meta.type))}catch(e){console.warn('probe',e)}onp(45);try{const th=await makeThumb(file,v.meta.type);if(th)await DB.put('thumbs',v.id,th)}catch(e){console.warn('thumb',e)}onp(70);v.media=await DB.saveMedia(v.id,file);onp(95);a.versions.push(v);a.cur=a.versions.length-1;if(a.versions.length>1){log('uploaded v'+a.versions.length+' of '+a.name);notify(`${ME.name} uploaded version ${a.versions.length} of ${a.name}`,'#/view/'+a.id)}return v}
async function stackVersion(target,src){const v=cur(src);target.versions.push(...src.versions);target.cur=target.versions.length-1;src.deleted=Date.now();src.stackedInto=target.id;save();render();toast(`Stacked as v${target.versions.length}`,'Undo',()=>{target.versions=target.versions.filter(x=>!src.versions.includes(x));target.cur=target.versions.length-1;src.deleted=null;save();render()})}
const thumbCache={};
async function thumbURL(a,vi){const v=vi!=null?a.versions[vi]:cur(a);if(!v)return null;if(thumbCache[v.id]!==undefined)return thumbCache[v.id];let b=null;try{b=await DB.get('thumbs',v.id)}catch(e){}thumbCache[v.id]=b?URL.createObjectURL(b):null;return thumbCache[v.id]}
function fileURL(file){return URL.createObjectURL(file)}
async function makeThumb(file,type,atSec){if(type==='Image'){const img=await loadImg(fileURL(file));return canvasBlob(img,img.naturalWidth,img.naturalHeight)}if(type==='Video'){const vid=document.createElement('video');vid.muted=true;vid.preload='auto';vid.src=fileURL(file);await new Promise((r,j)=>{vid.onloadedmetadata=r;vid.onerror=()=>j(new Error('cannot decode video'))});const t=atSec!=null?atSec:Math.min(Math.max(vid.duration*0.1,0.5),vid.duration||1);await new Promise(r=>{vid.onseeked=r;vid.currentTime=t});await new Promise(r=>setTimeout(r,60));const b=await canvasBlob(vid,vid.videoWidth,vid.videoHeight);URL.revokeObjectURL(vid.src);return b}if(type==='Audio'){return waveformThumb(file)}return null}
function loadImg(u){return new Promise((r,j)=>{const i=new Image();i.onload=()=>r(i);i.onerror=j;i.src=u})}
function canvasBlob(src,w,h,maxW=640){const s=Math.min(1,maxW/w);const c=document.createElement('canvas');c.width=Math.round(w*s);c.height=Math.round(h*s);c.getContext('2d').drawImage(src,0,0,c.width,c.height);return new Promise(r=>c.toBlob(r,'image/jpeg',.82))}
async function waveformThumb(file){try{const ac=new (window.OfflineAudioContext||window.webkitOfflineAudioContext)(1,44100*4,44100);const buf=await new AudioContext().decodeAudioData(await file.slice(0,8e6).arrayBuffer());const d=buf.getChannelData(0);const c=document.createElement('canvas');c.width=640;c.height=360;const x=c.getContext('2d');x.fillStyle='#101013';x.fillRect(0,0,640,360);x.fillStyle='#d79f46';const step=Math.floor(d.length/640)||1;for(let i=0;i<640;i++){let m=0;for(let k=0;k<step;k++)m=Math.max(m,Math.abs(d[i*step+k]||0));x.fillRect(i,180-m*160,1,m*320||1)}return new Promise(r=>c.toBlob(r,'image/jpeg',.85))}catch(e){return null}}
/* metadata probe: HTML media element + MP4/MOV box parse for codecs, fps, audio, color */
async function probeMedia(file,type){const m={};if(type==='Image'){const img=await loadImg(fileURL(file));m.w=img.naturalWidth;m.h=img.naturalHeight;if(/png|webp|gif|tif/i.test(file.type+file.name))m.alpha=true;return m}
 if(type==='Video'||type==='Audio'){const el=document.createElement(type==='Video'?'video':'audio');el.preload='metadata';el.src=fileURL(file);await new Promise((r)=>{el.onloadedmetadata=r;el.onerror=r;setTimeout(r,8000)});if(isFinite(el.duration))m.duration=el.duration;if(el.videoWidth){m.w=el.videoWidth;m.h=el.videoHeight}URL.revokeObjectURL(el.src);if(m.duration)m.bitrate=Math.round(file.size*8/m.duration);try{Object.assign(m,await parseMp4(file))}catch(e){}if(m.duration&&!m.bitrate)m.bitrate=Math.round(file.size*8/m.duration);if(m.duration&&m.vbitrate==null&&m.abitrate!=null)m.vbitrate=Math.max(0,m.bitrate-m.abitrate);if(type==='Video'&&!m.vcodec){const ext=file.name.split('.').pop().toLowerCase();m.vcodec=ext==='webm'?'VP9':ext==='mkv'?'H.264':null}if(type==='Audio'&&!m.acodec){const ext=file.name.split('.').pop().toLowerCase();m.acodec={mp3:'MP3',wav:'PCM',flac:'FLAC',aac:'AAC',m4a:'AAC',ogg:'Vorbis'}[ext]||null}if(!m.colorspace&&type==='Video')m.colorspace='BT709';if(!m.dynrange&&type==='Video')m.dynrange='SDR';return m}
 if(type==='Document'&&file.type==='application/pdf'){try{const txt=new TextDecoder('latin1').decode(await file.slice(0,Math.min(file.size,4e6)).arrayBuffer());const mm=txt.match(/\/Count\s+(\d+)/g);if(mm)m.pages=Math.max(...mm.map(x=>+x.match(/\d+/)[0]))}catch(e){}}return m}
async function parseMp4(file){const out={};const rd=async(off,len)=>new DataView(await file.slice(off,off+len).arrayBuffer());const str=(dv,o)=>String.fromCharCode(dv.getUint8(o),dv.getUint8(o+1),dv.getUint8(o+2),dv.getUint8(o+3));let off=0,moov=null;while(off<file.size-8){const h=await rd(off,16);let size=h.getUint32(0);const t=str(h,4);let hl=8;if(size===1){size=Number(h.getBigUint64(8));hl=16}else if(size===0)size=file.size-off;if(t==='moov'){if(size>80e6)break;moov=new DataView(await file.slice(off+hl,off+size).arrayBuffer());break}off+=size;if(size<8)break}if(!moov)return out;
 const boxes=(dv,s,e)=>{const r=[];let o=s;while(o+8<=e){let size=dv.getUint32(o);const t=str(dv,o+4);let hl=8;if(size===1){size=Number(dv.getBigUint64(o+8));hl=16}if(size<8)break;r.push({t,s:o+hl,e:Math.min(e,o+size)});o+=size}return r};
 const find=(dv,s,e,t)=>boxes(dv,s,e).find(b=>b.t===t);
 const traks=boxes(moov,0,moov.byteLength).filter(b=>b.t==='trak');
 for(const trak of traks){const tkhd=find(moov,trak.s,trak.e,'tkhd');const mdia=find(moov,trak.s,trak.e,'mdia');if(!mdia)continue;const mdhd=find(moov,mdia.s,mdia.e,'mdhd'),hdlr=find(moov,mdia.s,mdia.e,'hdlr'),minf=find(moov,mdia.s,mdia.e,'minf');if(!mdhd||!hdlr||!minf)continue;const ver=moov.getUint8(mdhd.s);const ts=ver===1?moov.getUint32(mdhd.s+20):moov.getUint32(mdhd.s+12);const dur=ver===1?Number(moov.getBigUint64(mdhd.s+24)):moov.getUint32(mdhd.s+16);const kind=str(moov,hdlr.s+8);const stbl=find(moov,minf.s,minf.e,'stbl');if(!stbl)continue;const stsd=find(moov,stbl.s,stbl.e,'stsd'),stsz=find(moov,stbl.s,stbl.e,'stsz');if(!stsd)continue;const entry=boxes(moov,stsd.s+8,stsd.e)[0];if(!entry)continue;const fourcc=entry.t;let count=0,bytes=0;if(stsz){const ss=moov.getUint32(stsz.s+4);count=moov.getUint32(stsz.s+8);if(ss)bytes=ss*count;else for(let i=0;i<count;i++)bytes+=moov.getUint32(stsz.s+12+i*4)}const secs=ts?dur/ts:0;
  if(kind==='vide'){out.vcodec={avc1:'H.264',avc3:'H.264',hvc1:'HEVC',hev1:'HEVC',av01:'AV1',vp09:'VP9',apch:'ProRes 422 HQ',apcn:'ProRes 422',apcs:'ProRes 422 LT',apco:'ProRes 422 Proxy',ap4h:'ProRes 4444',ap4x:'ProRes 4444 XQ',mjpa:'Motion JPEG',dvh1:'Dolby Vision',dvhe:'Dolby Vision'}[fourcc]||fourcc.toUpperCase();if(secs&&count)out.fps=count/secs;if(secs&&bytes)out.vbitrate=Math.round(bytes*8/secs);if(tkhd){const tv=moov.getUint8(tkhd.s);const wo=tv===1?tkhd.s+88:tkhd.s+76;out.w=out.w||Math.round(moov.getUint32(wo)/65536);out.h=out.h||Math.round(moov.getUint32(wo+4)/65536)}const w=moov.getUint16(entry.s+24),h=moov.getUint16(entry.s+26);if(w&&h){out.w=w;out.h=h}const depth=moov.getUint16(entry.s+74);if(depth)out.vbitdepth=depth>=32?10:8;if(depth===32||['ap4h','ap4x'].includes(fourcc))out.alpha=true;for(const sub of boxes(moov,entry.s+78,entry.e)){if(sub.t==='colr'){const typ=str(moov,sub.s);if(typ==='nclx'||typ==='nclc'){const pri=moov.getUint16(sub.s+4),trc=moov.getUint16(sub.s+6);out.colorspace={1:'BT709',9:'BT2020',5:'BT601 PAL',6:'BT601 NTSC',12:'P3 D65'}[pri]||'BT709';out.dynrange=trc===16?'HDR (PQ)':trc===18?'HDR (HLG)':'SDR'}}if(sub.t==='hvcC'||sub.t==='avcC'){}if(sub.t==='av1C'||sub.t==='hvcC'){const o=sub.t==='hvcC'?moov.getUint8(sub.s+21):0;if(o&&(o&7)>=2)out.vbitdepth=10}}}
  if(kind==='soun'){out.acodec={mp4a:'AAC','ac-3':'AC-3','ec-3':'E-AC-3',lpcm:'PCM',sowt:'PCM',twos:'PCM',alac:'ALAC',Opus:'Opus',fLaC:'FLAC',in24:'PCM 24-bit',in32:'PCM 32-bit'}[fourcc]||fourcc.toUpperCase();const ch=moov.getUint16(entry.s+16),ss=moov.getUint16(entry.s+18),sr=moov.getUint32(entry.s+24)/65536;out.achannels=ch||out.achannels;out.abitdepth=ss||out.abitdepth;if(sr)out.asr=Math.round(sr);if(['sowt','twos','lpcm','in24','in32'].includes(fourcc))out.acodec='PCM';if(secs&&bytes)out.abitrate=Math.round(bytes*8/secs);if(fourcc==='mp4a'&&!out.abitdepth)out.abitdepth=0;for(const sub of boxes(moov,entry.s+28,entry.e)){if(sub.t==='esds'){}}}
  if(kind==='vide'&&secs&&!out.duration)out.duration=secs}
 return out}
/* uploads panel */
function renderUploads(){const sp=$('#sidePanel');if(!sp.classList.contains('on')||sp.dataset.kind!=='uploads')return;const l=$('.list',sp);if(!l)return;l.innerHTML=U.length?U.slice().reverse().map(j=>`<div class="uprow"><div style="display:flex;justify-content:space-between;gap:8px"><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(j.name)}</span><small>${j.state==='done'?'Done':j.state==='error'?'Failed':j.state==='queued'?'Queued':j.pct+'%'}</small></div><div class="bar"><i style="width:${j.pct}%;${j.state==='error'?'background:var(--bad)':''}"></i></div><small>${fmtSize(j.size)}${j.err?' · '+esc(j.err):''}</small></div>`).join(''):`<div class="empty"><h3>No uploads</h3><p>Files you upload or drop into a project show their progress here.</p></div>`}
