function openSide(kind){const sp=$('#sidePanel');if(sp.classList.contains('on')&&sp.dataset.kind===kind)return closeSide();sp.dataset.kind=kind;sp.className='side-panel on';$$('.rail .ri[data-panel]').forEach(b=>b.classList.toggle('on',b.dataset.panel===kind));
 if(kind==='notifications'){const draw=(tab)=>{const list=S.notifs.filter(n=>tab==='all'||!n.read);sp.innerHTML=`<header>Notifications<button class="ib x" id="spX">${ico('x')}</button></header><div class="tabs"><button class="${tab==='all'?'on':''}" data-tab="all">All</button><button class="${tab==='unread'?'on':''}" data-tab="unread">Unread</button><button class="act" id="nRead">Mark all as read</button><button class="ib" id="nSet" title="Notification settings">${ico('gear')}</button></div><div class="list">${list.length?list.map(n=>`<div class="nrow ${n.read?'':'unread'}" data-n="${n.id}">${avatar(n.by,'av')}<div><b>${esc(n.by)}</b> ${esc(n.text.replace(n.by+' ',''))}<small>${ago(n.at)}</small></div></div>`).join(''):`<div class="empty"><h3>No Updates Yet</h3><p>New activity on your account will show here.</p></div>`}</div>`;$('#spX',sp).onclick=closeSide;$$('[data-tab]',sp).forEach(b=>b.onclick=()=>draw(b.dataset.tab));$('#nRead',sp).onclick=()=>{S.notifs.forEach(n=>n.read=true);save();renderBadges();draw(tab)};$('#nSet',sp).onclick=e=>menu(e.currentTarget,[{h:'Notify me about'},{n:'Comments & replies',toggle:S.prefs.nComments!==false,keep:true,fn:(e,el)=>{S.prefs.nComments=S.prefs.nComments===false;save();$('.tog',el).classList.toggle('on')}},{n:'Status changes',toggle:S.prefs.nStatus!==false,keep:true,fn:(e,el)=>{S.prefs.nStatus=S.prefs.nStatus===false;save();$('.tog',el).classList.toggle('on')}},{n:'Uploads',toggle:S.prefs.nUploads!==false,keep:true,fn:(e,el)=>{S.prefs.nUploads=S.prefs.nUploads===false;save();$('.tog',el).classList.toggle('on')}},{n:'Share link views',toggle:S.prefs.nViews!==false,keep:true,fn:(e,el)=>{S.prefs.nViews=S.prefs.nViews===false;save();$('.tog',el).classList.toggle('on')}}]);$$('[data-n]',sp).forEach(r=>r.onclick=()=>{const n=S.notifs.find(x=>x.id===r.dataset.n);n.read=true;save();renderBadges();closeSide();if(n.link)location.hash=n.link.replace(/^#/,'')})};draw('all')}
 else if(kind==='uploads'){sp.innerHTML=`<header>Uploads<span class="sp"></span><button class="btn ghost sm" id="upClear">Clear finished</button><button class="ib x" id="spX">${ico('x')}</button></header><div class="list"></div>`;$('#spX',sp).onclick=closeSide;$('#upClear',sp).onclick=()=>{U=U.filter(j=>j.state==='uploading'||j.state==='queued');renderUploads();renderBadges()};renderUploads()}
 else if(kind==='whatsnew'){sp.innerHTML=`<header>What’s New<button class="ib x" id="spX">${ico('x')}</button></header><div class="list" style="padding:12px 16px;font-size:13px;color:var(--fg2);line-height:1.6"><p><b style="color:var(--acc)">Review · step 04</b></p><p>Upload the final Premiere export, comment frame-by-frame with drawings, set Needs Review → In Progress → Approved, and send a share link to the manager. Approving an asset moves its pipeline card to <b>Ready To Post</b>.</p><p style="margin-top:10px"><b>Tips</b></p><ul style="padding-left:18px"><li>Drag a file onto an asset to stack it as a new version.</li><li>Press <kbd>?</kbd> for every keyboard shortcut.</li><li>Pick a media folder on disk so uploads live as real files.</li></ul></div>`;$('#spX',sp).onclick=closeSide}
 else if(kind==='shortcuts'){closeSide();shortcutsModal()}
 else if(kind==='support'){closeSide();modal(`<h3>Contact Support<button class="x">✕</button></h3><p>This Review step runs entirely inside the Bahlman Media app — nothing leaves this Mac unless you share a link.</p><div class="srow">${ico('desktop')}<span>Media is stored ${DB.hasFS?'in your chosen media folder (or the browser if none is set)':'in this browser'}</span></div><div class="srow">${ico('dl')}<span>Export project data any time from the ⋯ menu beside Assets</span></div><div class="srow">${ico('pipeline')}<span>Approving an asset moves its pipeline card to Ready To Post</span></div><div class="btns"><a class="btn ghost" href="mailto:itsseanrogers@gmail.com?subject=Bahlman%20Review%20support">Email Sean</a><button class="btn gold x">Close</button></div>`)}
 else if(kind==='feedback'){closeSide();modal(`<h3>Submit Feedback<button class="x">✕</button></h3><label>What should change?</label><textarea id="fbT" rows="4" placeholder="Tell us what’s missing or broken…"></textarea><div class="btns"><button class="btn ghost x">Cancel</button><button class="btn gold" id="fbOk">Send</button></div>`);$('#fbOk').onclick=()=>{const t=$('#fbT').value.trim();if(!t)return;S.feedback=(S.feedback||[]).concat({at:Date.now(),text:t});save();closeModal();toast('Thanks — feedback saved to the project notes')}}}
function closeSide(){const sp=$('#sidePanel');sp.className='side-panel';sp.innerHTML='';$$('.rail .ri[data-panel]').forEach(b=>b.classList.remove('on'))}
function shortcutsModal(){const g=(t,rows)=>`<h4>${t}</h4>`+rows.map(([k,d])=>`<div><span>${d}</span><kbd>${k}</kbd></div>`).join('');modal(`<h3>Keyboard shortcuts<button class="x">✕</button></h3><div class="shortcuts">${g('Playback',[['Space / K','Play / pause'],['J / L','Shuttle back / forward'],['← / →','Previous / next frame'],['⇧← / ⇧→','Back / forward 10 frames'],['↑ / ↓','Jump to previous / next comment'],['Home / End','Start / end'],['I / O','Set range in / out'],['⌥I / ⌥O','Clear range'],['M','Mute'],['F','Fullscreen'],['⇧L','Loop']])}${g('Viewer',[['C','Focus comment box'],['D','Draw annotation'],['⌘0','Zoom to 100%'],['+ / -','Zoom in / out'],['T','Zoom fit'],['Y','Zoom fill'],['G','Cycle guides'],['⌥4','Toggle details panel'],['⌥3','Toggle transcript'],['[ / ]','Previous / next asset'],['Esc','Back to project']])}${g('Project',[['⌘K','Search'],['⌘A','Select all'],['Delete','Delete selection'],['⌘D','Duplicate'],['R','Rename'],['N','New folder'],['U','Upload'],['S','Share'],['1 / 2','Grid / list layout'],['?','This dialog']])}</div>`,{wide:true})}
/* ─── search page ─── */
function renderSearch(q){const main=$('#main');main.innerHTML=topbar(`<b>Search</b>`)+`<div class="home" style="padding-top:20px"><div class="search" style="width:100%;height:44px;font-size:16px">${ico('search')}<input id="sQ" placeholder="Search for status, assignee, keywords, and more" value="${esc(q)}"></div><p style="color:var(--mut);font-size:13px;margin:12px 0">Start typing or tap a suggestion to begin</p><div class="hbar" style="flex-wrap:wrap;gap:6px">${['status:approved','status:needs review','status:in progress','type:video','type:image','type:audio','assignee:'+ME.name,'rating:5','has:comments','has:annotations','version:>1'].map(s=>`<button class="btn ghost sm" data-sug="${esc(s)}">${esc(s)}</button>`).join('')}</div><div id="sRes"></div></div>`;bindTopbar();const inp=$('#sQ');const run=()=>{const q=inp.value.trim();history.replaceState(null,'','#/search?q='+encodeURIComponent(q));const res=searchAssets(q);$('#sRes').innerHTML=q?(res.length?`<p style="color:var(--mut);font-size:12px;margin:6px 0 10px">${res.length} result${res.length>1?'s':''}</p><div class="list" style="--lc:3">${res.map(a=>`<div class="lrow" data-a="${a.id}"><span></span>${a.kind==='folder'?`<span class="fold">${ico('folder')}</span>`:`<img data-th="${a.id}">`}<span class="nm">${esc(a.name)}</span><span>${esc(proj(a.pid)?proj(a.pid).name:'')}</span><span>${a.kind==='asset'?statusPill(a.status):'Folder'}</span><span>${fmtDate(a.created)}</span><span></span></div>`).join('')}</div>`:'<div class="empty"><h3>No results</h3><p>Nothing matches that search.</p></div>'):''; $$('[data-a]').forEach(r=>r.onclick=()=>{const a=item(r.dataset.a);go(a.kind==='folder'?`/p/${a.pid}/f/${a.id}`:'/view/'+a.id)});$$('[data-th]').forEach(img=>thumbURL(item(img.dataset.th)).then(u=>{if(u)img.src=u}))};inp.oninput=run;$$('[data-sug]').forEach(b=>b.onclick=()=>{inp.value=b.dataset.sug;run();inp.focus()});if(q)run();inp.focus()}
function searchAssets(q){if(!q)return[];const terms=q.toLowerCase().match(/(\w+:(?:"[^"]*"|[^\s]+(?:\s[^\s:]+)*)|[^\s]+)/g)||[];const pending=[];const items=S.items.filter(i=>!i.deleted);return items.filter(a=>terms.every(t=>{const m=t.match(/^(\w+):(.*)$/);if(m){const k=m[1],v=m[2].replace(/"/g,'').trim();if(k==='status')return statusName(a.status).toLowerCase().includes(v);if(k==='type')return(metaOf(a).type||'').toLowerCase()===v||(v==='folder'&&a.kind==='folder');if(k==='assignee')return(a.assignee||'').toLowerCase().includes(v);if(k==='rating')return String(a.rating||0)===v;if(k==='has')return v==='comments'?(a.comments||[]).length>0:v==='annotations'?(a.comments||[]).some(c=>c.ann):v==='transcript'?!!a.transcript:true;if(k==='version')return v.startsWith('>')?a.versions.length>+v.slice(1):a.versions.length===+v;if(k==='keyword'||k==='keywords')return(a.keywords||[]).some(x=>x.toLowerCase().includes(v));if(k==='uploader')return(a.uploader||'').toLowerCase().includes(v)}const hay=[a.name,a.notes,(a.keywords||[]).join(' '),a.assignee,statusName(a.status),(a.comments||[]).map(c=>c.text).join(' '),a.transcript?a.transcript.segs.map(s=>s.text).join(' '):'',metaOf(a).type].join(' ').toLowerCase();return hay.includes(t)}))}
/* ─── collections / recently deleted / shares table ─── */
function smartItems(c,pid){const as=S.items.filter(i=>i.kind==='asset'&&!i.deleted&&(!pid||i.pid===pid));switch(c.smart){case'video':return as.filter(a=>metaOf(a).type==='Video');case'image':return as.filter(a=>metaOf(a).type==='Image');case'audio':return as.filter(a=>metaOf(a).type==='Audio');case'needs_review':return as.filter(a=>a.status==='needs_review');case'approved':return as.filter(a=>a.status==='approved');default:return c.items.map(item).filter(Boolean)}}
function renderCollections(pr,cid){const main=$('#main');const c=cid?S.collections.find(x=>x.id===cid):null;main.innerHTML=topbar(crumbsFor(pr,null,c?c.name:'Collections'))+`<div class="body"></div>`;const body=$('.body',main);body.appendChild(sidebar(pr,null,'collections'));const ct=document.createElement('div');ct.className='content';
 if(!c){const draw=(q)=>{const list=S.collections.filter(x=>!q||x.name.toLowerCase().includes(q));ct.innerHTML=`<div class="toolbar"><div class="search" style="width:220px">${ico('search')}<input id="cQ" placeholder="Search" value="${esc(q)}"></div><span class="sp"></span><button class="btn gold" id="cNew">${ico('plus')}New Collection</button></div><div class="scroll"><table class="table"><tr><th>Name</th><th>Created by</th><th>Private</th><th>Created on ↓</th><th></th></tr>${list.map(x=>`<tr data-c="${x.id}" style="cursor:pointer"><td class="nm">${ico('coll')} ${esc(x.name)} <span style="color:var(--mut)">· ${smartItems(x,pr.id).length}</span></td><td><span class="av"><i>${esc(ini(x.by))}</i>${esc(x.by)}</span></td><td><span class="tog ${x.private?'on':''}" data-priv="${x.id}"></span></td><td>${fmtDate(x.created)}</td><td>${x.smart?'':`<button class="ib" data-cm="${x.id}">${ico('more')}</button>`}</td></tr>`).join('')}</table><div class="tfoot">${list.length} Collection${list.length===1?'':'s'}</div></div>`;$('#cQ',ct).oninput=e=>{draw(e.target.value.trim().toLowerCase());$('#cQ',ct).focus()};$('#cNew',ct).onclick=()=>prompt2('New Collection','Name','',n=>{if(n){S.collections.push({id:uid(),name:n,by:ME.name,private:false,created:Date.now(),smart:null,items:[],pid:pr.id});save();draw('')}},'Create');$$('[data-c]',ct).forEach(r=>r.onclick=e=>{if(e.target.closest('[data-priv],[data-cm]'))return;go(`/p/${pr.id}/collections/${r.dataset.c}`)});$$('[data-priv]',ct).forEach(t=>t.onclick=()=>{const x=S.collections.find(y=>y.id===t.dataset.priv);x.private=!x.private;save();t.classList.toggle('on',x.private)});$$('[data-cm]',ct).forEach(b=>b.onclick=()=>{const x=S.collections.find(y=>y.id===b.dataset.cm);menu(b,[{n:'Rename',ic:'edit',fn:()=>prompt2('Rename','Name',x.name,n=>{if(n){x.name=n;save();draw('')}})},{n:'Delete',ic:'trash',danger:true,fn:()=>{S.collections=S.collections.filter(y=>y!==x);save();draw('')}}])})};draw('')}
 else{const list=smartItems(c,pr.id);ct.innerHTML=`<div class="toolbar"><button class="tb" id="tAppear">${ico('eye')}Appearance</button><span class="sp"></span>${c.smart?'<span style="font-size:12px;color:var(--mut)">Smart collection — updates automatically</span>':`<button class="btn ghost sm" id="cRemove" disabled>Remove from collection</button>`}</div><div class="scroll">${list.length?`<div class="grid ${S.prefs.size}">${list.map(a=>`<div class="card" data-id="${a.id}"><div class="th"><img data-th="${a.id}">${metaOf(a).duration?`<span class="dur">${fmtDur(metaOf(a).duration)}</span>`:''}<span class="chk" data-chk="${a.id}"></span></div><div class="in"><div class="nm">${esc(a.name)}</div><div class="sub"><span>${esc(a.uploader)} • ${fmtDate(a.created)}</span><button class="mo" data-mo="${a.id}">${ico('more')}</button></div><div class="fields"><div class="fcell edit" data-fk="status" data-fid="${a.id}"><div class="k">${ico('check')}Status</div><div class="v">${statusPill(a.status)}</div></div></div></div></div>`).join('')}</div>`:`<div class="empty"><h3>Nothing here yet</h3><p>${c.smart?'Assets that match this collection will appear automatically.':'Use “Add to collection” on any asset.'}</p></div>`}</div>`;body.appendChild(ct);bindCards($('.scroll',ct),pr,null);ct._updateSel=()=>{$$('.card',ct).forEach(el=>{const on=SEL.has(el.dataset.id);el.classList.toggle('sel',on);$('.chk',el).classList.toggle('on',on);$('.chk',el).textContent=on?'✓':''});const rm=$('#cRemove',ct);if(rm)rm.disabled=!SEL.size};const reAp=()=>{save();render();const b=$('#tAppear');if(b)appearanceMenu(b,S.prefs,reAp)};$('#tAppear',ct).onclick=e=>appearanceMenu(e.currentTarget,S.prefs,reAp);const rm=$('#cRemove',ct);if(rm)rm.onclick=()=>{c.items=c.items.filter(id=>!SEL.has(id));save();render()};return}
 body.appendChild(ct);bindTopbar()}
function renderDeleted(pr){const main=$('#main');main.innerHTML=topbar(crumbsFor(pr,null,'Recently Deleted'))+`<div class="body"></div>`;const body=$('.body',main);body.appendChild(sidebar(pr,null,'deleted'));const ct=document.createElement('div');ct.className='content';const list=S.items.filter(i=>i.pid===pr.id&&i.deleted).sort((a,b)=>b.deleted-a.deleted);ct.innerHTML=`<div class="toolbar"><span style="font-size:13px;color:var(--fg2)">Items are kept for 30 days, then removed permanently.</span><span class="sp"></span><button class="btn danger sm" id="dEmpty" ${list.length?'':'disabled'}>Empty Recently Deleted</button></div><div class="scroll">${list.length?`<table class="table"><tr><th>Name</th><th>Type</th><th>Deleted</th><th>Removed in</th><th></th></tr>${list.map(i=>`<tr><td class="nm">${ico(i.kind==='folder'?'folder':typeIcon(i))} ${esc(i.name)}</td><td>${i.kind==='folder'?'Folder':esc(metaOf(i).type||'')}</td><td>${ago(i.deleted)}</td><td>${Math.max(0,30-Math.floor((Date.now()-i.deleted)/86400e3))} days</td><td style="text-align:right"><button class="btn ghost sm" data-res="${i.id}">${ico('restore')}Restore</button> <button class="btn danger sm" data-perm="${i.id}">Delete permanently</button></td></tr>`).join('')}</table>`:`<div class="empty"><h3>Recently Deleted is empty</h3><p>Deleted folders and assets can be restored from here for 30 days.</p></div>`}</div>`;body.appendChild(ct);bindTopbar();
 $$('[data-res]',ct).forEach(b=>b.onclick=()=>{const i=anyItem(b.dataset.res);i.deleted=null;if(i.stackedInto){const t=item(i.stackedInto);if(t)t.versions=t.versions.filter(v=>!i.versions.includes(v))}if(i.parent&&!item(i.parent))i.parent=null;save();render();toast('Restored')});
 const perm=async ids=>{for(const id of ids){const i=anyItem(id);if(!i)continue;for(const v of i.versions){await DB.removeMedia(v.id,v.media);try{await DB.del('thumbs',v.id)}catch(e){}}S.items=S.items.filter(x=>x.id!==id)}save();render()};
 $$('[data-perm]',ct).forEach(b=>b.onclick=()=>confirmBox('Delete permanently?','This cannot be undone. The media file is removed too.','Delete permanently',()=>perm([b.dataset.perm])));
 $('#dEmpty',ct).onclick=()=>confirmBox('Empty Recently Deleted?',`${list.length} item${list.length>1?'s':''} will be removed for good.`,'Empty',()=>perm(list.map(i=>i.id)))}
function renderShares(pr){const main=$('#main');main.innerHTML=topbar(crumbsFor(pr,null,'All Share Links'))+`<div class="body"></div>`;const body=$('.body',main);body.appendChild(sidebar(pr,null,'shares'));const ct=document.createElement('div');ct.className='content';let sortK='created',dir=-1,q='';const draw=()=>{let list=S.shares.filter(s=>s.pid===pr.id&&(!q||s.title.toLowerCase().includes(q)));list.sort((a,b)=>{const x=a[sortK]||'',y=b[sortK]||'';return(typeof x==='string'?x.localeCompare(y):(x>y)-(x<y))*dir});const th=(k,n)=>`<th data-k="${k}">${n}${sortK===k?(dir>0?' ↑':' ↓'):''}</th>`;ct.innerHTML=`<div class="toolbar"><div class="search" style="width:220px">${ico('search')}<input id="shQ" placeholder="Search for Shares" value="${esc(q)}"></div><span class="sp"></span><button class="btn gold" id="shNew">${ico('plus')}Create Share Link</button></div><div class="scroll"><table class="table"><tr><th><span class="chk" id="shAll"></span></th>${th('title','Title')}<th>Link</th>${th('enabled','Visibility')}${th('public','Access type')}${th('lastViewed','Last viewed')}${th('views','Views')}<th>Activity</th>${th('by','Created by')}${th('created','Created on')}</tr>${list.map(s=>`<tr data-s="${s.id}"><td><span class="chk ${SEL.has(s.id)?'on':''}" data-chk="${s.id}">${SEL.has(s.id)?'✓':''}</span></td><td class="nm" style="cursor:pointer" data-open="${s.id}">${esc(s.title)}</td><td><span class="linkchip" data-copy="${s.id}">bm.review/${s.code}</span></td><td><span class="tog ${s.enabled?'on':''}" data-en="${s.id}"></span></td><td>${s.public?'Public':'Secure'}</td><td>${s.lastViewed?ago(s.lastViewed):'—'}</td><td>${s.views||0}</td><td><a href="#/p/${pr.id}/share/${s.id}?tab=activity" style="color:var(--acc)">View Activity</a></td><td><span class="av"><i>${esc(ini(s.by))}</i>${esc(s.by)}</span></td><td>${fmtDate(s.created)}</td></tr>`).join('')}</table><div class="tfoot">${list.length} Share${list.length===1?'':'s'}</div>${SEL.size?`<div class="selbar"><b>${SEL.size} selected</b><button class="x" id="shX">✕</button><button class="btn soft sm" id="shDis">Disable</button><button class="btn danger sm" id="shDel">Delete</button></div>`:''}</div>`;
  $('#shQ',ct).oninput=e=>{q=e.target.value.trim().toLowerCase();draw();$('#shQ',ct).focus();$('#shQ',ct).setSelectionRange(99,99)};$('#shNew',ct).onclick=()=>createShare(pr.id,[]);$$('th[data-k]',ct).forEach(t=>t.onclick=()=>{if(sortK===t.dataset.k)dir=-dir;else{sortK=t.dataset.k;dir=1}draw()});$$('[data-open]',ct).forEach(t=>t.onclick=()=>go(`/p/${pr.id}/share/${t.dataset.open}`));$$('[data-copy]',ct).forEach(t=>t.onclick=()=>copyText(shareURL(S.shares.find(s=>s.id===t.dataset.copy)),'Link copied'));$$('[data-en]',ct).forEach(t=>t.onclick=()=>{const s=S.shares.find(x=>x.id===t.dataset.en);s.enabled=!s.enabled;save();t.classList.toggle('on',s.enabled)});$$('[data-chk]',ct).forEach(c=>c.onclick=()=>{SEL.has(c.dataset.chk)?SEL.delete(c.dataset.chk):SEL.add(c.dataset.chk);draw()});$('#shAll',ct).onclick=()=>{if(SEL.size)SEL.clear();else list.forEach(s=>SEL.add(s.id));draw()};const x=$('#shX',ct);if(x){x.onclick=()=>{SEL.clear();draw()};$('#shDis',ct).onclick=()=>{S.shares.forEach(s=>{if(SEL.has(s.id))s.enabled=false});save();SEL.clear();draw()};$('#shDel',ct).onclick=()=>confirmBox('Delete share links?',`${SEL.size} link${SEL.size>1?'s':''} will stop working.`,'Delete',()=>{S.shares=S.shares.filter(s=>!SEL.has(s.id));save();SEL.clear();draw()})}};
 body.appendChild(ct);bindTopbar();draw()}
/* ─── pipeline link picker ─── */
function linkPipeline(a){const cards=pipeCards().sort((x,y)=>(x.pipeline||'').localeCompare(y.pipeline||''));modal(`<h3>Link to pipeline card<button class="x">✕</button></h3><p>Approving this asset will move the linked card to <b>Ready To Post</b>; “Needs Review” sets it to <b>Ready For Review</b>.</p><div class="search" style="width:100%;margin-bottom:8px">${ico('search')}<input id="lpQ" placeholder="Search cards"></div><div style="max-height:46vh;overflow:auto" id="lpList">${cards.map(c=>`<div class="srow btnrow" data-card="${c.id}">${ico('pipeline')}<span>${esc(c.title||'Untitled')}</span><span class="sp"></span><span class="val">${esc(c.pipeline||'')}</span>${a.card===c.id?`<span style="color:var(--acc)">${ico('check')}</span>`:''}</div>`).join('')||'<p>No pipeline cards found. Open the Video Pipeline once so its board is loaded.</p>'}</div><div class="btns">${a.card?`<button class="btn ghost" id="lpUn">Unlink</button>`:''}<button class="btn ghost" id="lpNo">Close</button></div>`);$('#lpNo').onclick=closeModal;const un=$('#lpUn');if(un)un.onclick=()=>{a.card=null;save();closeModal();toast('Unlinked')};$('#lpQ').oninput=e=>{const q=e.target.value.toLowerCase();$$('#lpList [data-card]').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')};$$('#lpList [data-card]').forEach(r=>r.onclick=()=>{a.card=r.dataset.card;save();syncPipeline(a);closeModal();toast('Linked to pipeline card')})}
/* ─── global keys ─── */
document.addEventListener('keydown',e=>{const tag=(e.target.tagName||'').toLowerCase();const typing=tag==='input'||tag==='textarea'||e.target.isContentEditable;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();const q=$('#tbQ');if(q)q.focus();else go('/search');return}if(typing)return;if(e.key==='?'){shortcutsModal();return}const r=route().parts;if(r[0]==='p'&&(!r[2]||r[2]==='f')){const pr=proj(r[1]);const fid=r[3]||null;const c=$('.content');if((e.metaKey||e.ctrlKey)&&e.key==='a'){e.preventDefault();children(pr.id,fid).forEach(i=>SEL.add(i.id));c._updateSel&&c._updateSel()}else if(e.key==='Delete'||e.key==='Backspace'){if(SEL.size)deleteItems([...SEL])}else if((e.metaKey||e.ctrlKey)&&e.key==='d'){e.preventDefault();if(SEL.size)duplicateItems([...SEL])}else if(e.key==='n')newFolder(pr.id,fid);else if(e.key==='u')pickUpload(pr.id,fid);else if(e.key==='s'){if(SEL.size)createShare(pr.id,[...SEL])}else if(e.key==='r'&&SEL.size===1){const it=item([...SEL][0]);prompt2('Rename','Name',it.name,n=>{if(n){it.name=n;save();render()}})}else if(e.key==='1'||e.key==='2'){S.prefs.layout=e.key==='1'?'grid':'list';save();render()}}});
/* ─── boot ─── */
async function boot(){await loadState();renderBadges();bindUploadInputs();$$('.rail .ri[data-panel]').forEach(b=>b.onclick=()=>openSide(b.dataset.panel));$('#meBtn').onclick=e=>menu(e.currentTarget,[{h:ME.name},{n:'Keyboard shortcuts',ic:'field',kbd:'?',fn:shortcutsModal},{n:'Choose media folder on disk',ic:'desktop',fn:chooseMediaDir},{n:'Reconnect media folder',ic:'restore',fn:()=>DB.reconnectDir().then(d=>toast(d?'Reconnected '+d.name:'No folder saved'))},{n:'Export project data',ic:'dl',fn:exportState},'-',{n:'Reset Review app',ic:'trash',danger:true,fn:()=>confirmBox('Reset everything?','All projects, assets, comments and share links in Review will be removed.','Reset',async()=>{for(const i of S.items)for(const v of i.versions)await DB.removeMedia(v.id,v.media);S=fresh();save();render()})}],{above:true});
 if(EMBED){$$('.rail a[href^="../"]').forEach(a=>{a.onclick=e=>{e.preventDefault();parent.postMessage({bm:'step',step:a.href.includes('Pipeline')?'pipeline':a.href.includes('Ideate')?'ideate':a.href.includes('People')?'people':'library'},'*')}})}
 addEventListener('storage',e=>{if(e.key==='bm.pipeline.ping'&&route().parts.length===0)render()});
 if(!location.hash)location.hash='#/';render()}
